package com.game_manager.gm.notification; import com.game_manager.gm.notification.dto.NotificationResponse; import java.util.UUID; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional;
@Service public class WorkflowNotificationGateway {private final NotificationRepository repository;private final NotificationRealtimeHub realtime;public WorkflowNotificationGateway(NotificationRepository r,NotificationRealtimeHub h){repository=r;realtime=h;}@Transactional public void send(UUID source,UUID recipient,NotificationType type,String title,String body){if(repository.existsBySourceEventIdAndRecipientIdAndType(source,recipient,type))return;Notification n=new Notification();n.setSourceEventId(source);n.setRecipientId(recipient);n.setType(type);n.setPriority(type==NotificationType.WORKFLOW_ESCALATED?NotificationPriority.HIGH:NotificationPriority.NORMAL);n.setTitle(title);n.setBody(body);n.setDeepLink("/workflows");n.setInAppVisible(true);repository.saveAndFlush(n);realtime.send(recipient,NotificationResponse.from(n));}}
